namespace sv_7c41f9a2df77432ab6246b46f3919914.Services;

public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "warehouse-a";
    public string SelectedWarehouseName { get; private set; } = "Warehouse A";

    public event Action? OnChange;

    public static readonly List<(string Id, string Name)> AvailableWarehouses =
    [
        ("warehouse-a", "Warehouse A"),
        ("warehouse-b", "Warehouse B"),
        ("warehouse-c", "Warehouse C"),
        ("warehouse-d", "Warehouse D"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = AvailableWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse == default) return;

        SelectedWarehouseId = warehouse.Id;
        SelectedWarehouseName = warehouse.Name;
        OnChange?.Invoke();
    }
}

namespace sv_7c41f9a2df77432ab6246b46f3919914.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts for the current warehouse.
/// Fires OnAlertCountChanged whenever new data arrives so all subscribers can update.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _pollingConsumers;

    public int CurrentAlertCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning the number of low-stock items.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Starts the 10-second polling loop if not already running.
    /// </summary>
    public void StartPolling()
    {
        _pollingConsumers++;
        if (_pollingConsumers == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Call when a component that needs polling is disposed.
    /// Stops polling when no consumers remain.
    /// </summary>
    public void StopPolling()
    {
        _pollingConsumers = Math.Max(0, _pollingConsumers - 1);
        if (_pollingConsumers == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
        }
    }

    /// <summary>
    /// Immediately refresh the alert count (e.g., on warehouse change).
    /// </summary>
    public async Task RefreshAsync()
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
                OnAlertCountChanged?.Invoke();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async void HandleWarehouseChanged()
    {
        // Re-fetch alerts for the newly selected warehouse
        await RefreshAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _cts?.Cancel();
        _timer?.Dispose();
    }
}

